    public struct DetLinearKFModelDouble : IdoubleKFModel
    {
        public doubleMxN A;
        public doubleMxN B;
        public doubleN Scratch;

        public void F(in doubleN x, in doubleN u, ref doubleN xNext)
        {
            Blas.dot(in A, in x, ref xNext);
            Blas.dot(in B, in u, ref Scratch);
            xNext.addInPlace(Scratch);
        }

        public void JacobianF(in doubleN x, in doubleN u, ref doubleMxN J)
        {
            for (int r = 0; r < A.M_Rows; r++) for (int c = 0; c < A.N_Cols; c++) J[r, c] = A[r, c];
        }
    }

    public struct DetLinearKFMeasDouble : IdoubleKFMeasurement
    {
        public doubleMxN Hmat;

        public void H(in doubleN x, ref doubleN z) => Blas.dot(in Hmat, in x, ref z);

        public void JacobianH(in doubleN x, ref doubleMxN J)
        {
            for (int r = 0; r < Hmat.M_Rows; r++) for (int c = 0; c < Hmat.N_Cols; c++) J[r, c] = Hmat[r, c];
        }
    }

    public struct DetPolyResidualDouble : IdoubleResidualFunction
    {
        public doubleN X, Y;

        public void Residuals(in doubleN p, ref doubleN r)
        {
            for (int i = 0; i < r.N; i++)
            {
                double x = X[i];
                double model = p[0] + p[1] * x + p[2] * x * x;
                r[i] = model - Y[i];
            }
        }
    }

    public struct DetPolyCurveModelDouble : IdoubleCurveModel
    {
        public double Eval(double x, in doubleN p) => p[0] + p[1] * x + p[2] * x * x;
    }

